INSERT INTO public.questions (domain, difficulty, question, options, correct, explanation, know_this, state_specific) VALUES
('insurance_regulation', 'easy', 'Under ch. 628, Wis. Stat., the primary purpose of licensing insurance intermediaries is to:', '["Ensure that only competent and trustworthy persons sell insurance to the public","Generate licensing fee revenue for the state","Limit the total number of producers in Wisconsin","Guarantee minimum profits for insurers"]'::jsonb, 'Ensure that only competent and trustworthy persons sell insurance to the public', 'Licensing under ch. 628 is a consumer-protection measure designed to keep unqualified or untrustworthy persons out of the business of insurance.', 'Licensing exists to protect the public, not to raise revenue.', 'Wisconsin'),
('insurance_regulation', 'medium', 'Which person is required to hold a Wisconsin intermediary license?', '["An individual who solicits and negotiates life insurance contracts for compensation","A clerical employee who processes applications but never solicits business","An attorney who occasionally discusses estate planning with clients","A newspaper that publishes an insurer''s advertisements"]'::jsonb, 'An individual who solicits and negotiates life insurance contracts for compensation', 'A license is required for persons who solicit, negotiate, or place insurance for compensation; purely clerical or incidental activities do not require licensure.', 'Solicit or negotiate for pay = license required.', 'Wisconsin'),
('insurance_regulation', 'medium', 'Wisconsin statutes generally refer to a licensed insurance producer or agent as a(n):', '["Intermediary","Solicitor","Adjuster","Broker-dealer"]'::jsonb, 'Intermediary', 'Wisconsin''s insurance code (ch. 628) uses the term intermediary for the persons other states call producers or agents.', 'In WI statutes, producer = intermediary.', 'Wisconsin'),
('insurance_regulation', 'medium', 'A Wisconsin resident applying for a life insurance license must complete how much approved prelicensing education, and within what time frame before testing?', '["20 hours, completed no more than one year before the exam","40 hours, completed no more than two years before the exam","10 hours, completed no more than six months before the exam","No prelicensing education is required in Wisconsin"]'::jsonb, '20 hours, completed no more than one year before the exam', 'Wis. Admin. Code Ins 26.04 requires at least 20 hours of commissioner-approved prelicensing education completed within one year before the licensing exam.', 'WI prelicensing = 20 hours within 1 year of testing.', 'Wisconsin'),
('insurance_regulation', 'easy', 'The primary purpose of continuing education requirements for license renewal is to:', '["Maintain the ongoing competence of licensed intermediaries","Increase state licensing revenue","Reduce the number of active licensees","Train producers to underwrite policies"]'::jsonb, 'Maintain the ongoing competence of licensed intermediaries', 'Continuing education is required for license renewal so that intermediaries stay current on products, law, and ethics throughout their careers.', 'CE keeps licensees competent after the initial exam.', 'Wisconsin'),
('insurance_regulation', 'medium', 'Under s. 628.09, the commissioner may issue a temporary intermediary license without an examination primarily to:', '["Allow an existing book of business to be serviced when a producer dies or becomes disabled","Let new applicants sell insurance while studying for the exam","Reward agencies that meet production goals","License nonresident producers during open enrollment"]'::jsonb, 'Allow an existing book of business to be serviced when a producer dies or becomes disabled', 'Temporary licenses exist so that a deceased or disabled producer''s business can continue to be serviced without interruption; they are not a way to bypass the exam for ordinary applicants.', 'Temporary license = servicing a book after death or disability.', 'Wisconsin'),
('insurance_regulation', 'medium', 'Under s. 628.51, a Wisconsin intermediary license may be denied or revoked if the applicant intends to use it primarily to:', '["Write insurance on the licensee''s own life, property, or interests","Sell insurance to members of the general public","Represent more than one insurer","Sell only one line of insurance"]'::jsonb, 'Write insurance on the licensee''s own life, property, or interests', 'The controlled business rule prevents people from obtaining a license mainly to collect commissions on their own risks or those of close associates rather than serving the public.', 'Controlled business = license used mainly for your own risks.', 'Wisconsin'),
('insurance_regulation', 'medium', 'Under s. 628.61, an intermediary may share a commission on a life insurance sale with:', '["Another licensed intermediary","Any person who referred the client","The purchasing client","An unlicensed office assistant"]'::jsonb, 'Another licensed intermediary', 'Commissions may generally be shared only with other appropriately licensed intermediaries; paying unlicensed persons or the client is prohibited.', 'Commissions may be split only with licensed intermediaries.', 'Wisconsin'),
('insurance_regulation', 'medium', 'An intermediary who wants to transact insurance business under a trade (assumed) name must:', '["Notify the commissioner before using the assumed name","Simply begin using the name once it is registered with the county","Obtain approval from each appointed insurer only","Do nothing; assumed names are unregulated"]'::jsonb, 'Notify the commissioner before using the assumed name', 'Licensees must keep OCI informed of the names under which they do business, including assumed or trade names, before transacting under them.', 'Assumed names must be reported to the commissioner.', 'Wisconsin'),
('insurance_regulation', 'hard', 'A Wisconsin intermediary has an administrative action taken against their license by another state''s insurance regulator. The intermediary must:', '["Report the action to the Wisconsin commissioner","Do nothing unless the other state revoked the license","Disclose the action only at the next renewal","Notify only the insurers they represent"]'::jsonb, 'Report the action to the Wisconsin commissioner', 'Licensees are required to report administrative actions taken against them in other jurisdictions to OCI; waiting for renewal or staying silent violates the reporting requirement.', 'Out-of-state discipline must be reported to OCI.', 'Wisconsin'),
('insurance_regulation', 'easy', 'When a licensed intermediary moves to a new business address, the intermediary must:', '["Notify the commissioner of the change","Apply for an entirely new license","Retake the licensing examination","Notify only their clients"]'::jsonb, 'Notify the commissioner of the change', 'Licensees must keep their address and contact information current with OCI so the regulator can reach them; a move does not require a new license or exam.', 'Address changes get reported to OCI.', 'Wisconsin'),
('insurance_regulation', 'medium', 'Which individual is NOT required to hold an intermediary license?', '["A salaried office employee who performs only clerical duties and never solicits insurance","An individual paid commission to solicit life insurance applications","A person who negotiates policy terms on behalf of applicants for a fee","A telemarketer paid per completed life insurance sale"]'::jsonb, 'A salaried office employee who performs only clerical duties and never solicits insurance', 'Licensing attaches to soliciting and negotiating insurance for compensation; purely administrative or clerical staff who never solicit are exempt.', 'Clerical-only staff do not need a license.', 'Wisconsin'),
('insurance_regulation', 'medium', 'Which act would most likely subject an intermediary to license suspension or revocation?', '["Intentionally misrepresenting the terms of a policy to a client","Charging the insurer''s filed premium rate","Recommending coverage that the client ultimately declined","Referring a client to another licensed intermediary"]'::jsonb, 'Intentionally misrepresenting the terms of a policy to a client', 'Misrepresentation in the sale of insurance is a core ground for disciplinary action; the other choices describe ordinary, lawful conduct.', 'Misrepresenting a policy = discipline.', 'Wisconsin'),
('insurance_regulation', 'medium', 'In addition to license suspension or revocation, the commissioner may enforce Wisconsin insurance laws by:', '["Ordering monetary forfeitures for violations","Imposing prison sentences directly","Seizing a licensee''s personal assets without a hearing","Canceling policyholders'' contracts as punishment"]'::jsonb, 'Ordering monetary forfeitures for violations', 'Under s. 601.64, the commissioner may assess monetary forfeitures (civil fines) and pursue other enforcement remedies; only courts can impose criminal sentences.', 'Commissioner fines = forfeitures under s. 601.64.', 'Wisconsin'),
('insurance_regulation', 'hard', 'Before issuing an intermediary license, the commissioner must be satisfied that the applicant:', '["Is competent and trustworthy and intends to act in good faith as an intermediary","Has at least one year of insurance experience","Holds a college degree in business or finance","Has purchased errors and omissions insurance"]'::jsonb, 'Is competent and trustworthy and intends to act in good faith as an intermediary', 'Section 628.04 conditions licensure on competence and trustworthiness; experience, degrees, and E&O coverage are not statutory licensing prerequisites.', 'License standard = competent and trustworthy.', 'Wisconsin'),
('insurance_regulation', 'medium', 'When the commissioner seeks to revoke an intermediary''s license, the licensee is generally entitled to:', '["Notice and an opportunity for a hearing under Wisconsin''s administrative procedure law","Immediate revocation with no recourse","A jury trial before any action is taken","Review only by the governor"]'::jsonb, 'Notice and an opportunity for a hearing under Wisconsin''s administrative procedure law', 'License revocations are administrative actions subject to due process under ch. 227, which provides notice and hearing rights before the agency.', 'Revocation requires notice and a ch. 227 hearing.', 'Wisconsin'),
('insurance_regulation', 'hard', 'A resident intermediary who fails to complete required continuing education by the renewal deadline will generally:', '["Have the license lapse rather than renew until the requirement is satisfied","Receive an automatic exemption for that period","Pay a small fee and keep the license active indefinitely","Lose only the most recently added line of authority"]'::jsonb, 'Have the license lapse rather than renew until the requirement is satisfied', 'Continuing education is a condition of renewal; a licensee who has not satisfied it cannot renew until the deficiency is corrected.', 'No CE = no renewal.', 'Wisconsin'),
('insurance_regulation', 'easy', 'The state official charged with administering and enforcing Wisconsin''s insurance laws is the:', '["Commissioner of Insurance","State Treasurer","Attorney General","Secretary of Revenue"]'::jsonb, 'Commissioner of Insurance', 'The Office of the Commissioner of Insurance (OCI) regulates the Wisconsin insurance market, and the commissioner heads that office.', 'OCI and its commissioner run WI insurance regulation.', 'Wisconsin'),
('insurance_regulation', 'medium', 'Under s. 601.41, the commissioner''s general powers include:', '["Promulgating rules necessary to administer and enforce the insurance laws","Setting federal tax policy for insurance products","Owning and operating a state life insurance company","Approving producers'' individual sales goals"]'::jsonb, 'Promulgating rules necessary to administer and enforce the insurance laws', 'Section 601.41 gives the commissioner broad authority to issue administrative rules and take actions needed to enforce the insurance code.', 's. 601.41 = commissioner''s general duties and rulemaking power.', 'Wisconsin'),
('insurance_regulation', 'medium', 'Under s. 601.42, the commissioner may require an insurer or intermediary to:', '["Provide reports, replies to inquiries, and other information about its business","Lower its premium rates on demand","Hire a minimum number of Wisconsin employees","Merge with a financially stronger insurer"]'::jsonb, 'Provide reports, replies to inquiries, and other information about its business', 'Section 601.42 authorizes the commissioner to demand reports and answers from regulated persons so OCI can monitor the market.', 's. 601.42 = commissioner can demand reports and replies.', 'Wisconsin');
INSERT INTO public.questions (domain, difficulty, question, options, correct, explanation, know_this, state_specific) VALUES
('insurance_regulation', 'medium', 'Under s. 601.43, the commissioner may examine the affairs and records of a Wisconsin insurer:', '["Whenever the commissioner deems it necessary","Only once every ten years","Only after a policyholder files a complaint","Only with a court order"]'::jsonb, 'Whenever the commissioner deems it necessary', 'The examination power is discretionary and ongoing; the commissioner does not need a complaint or court order to examine a regulated company''s records.', 'OCI can examine insurers whenever it deems necessary.', 'Wisconsin'),
('insurance_regulation', 'easy', 'State regulation of insurer solvency exists primarily to:', '["Ensure insurers remain financially able to pay claims","Maximize insurer investment returns","Standardize producer commissions","Keep premium taxes low"]'::jsonb, 'Ensure insurers remain financially able to pay claims', 'Solvency regulation protects policyholders by monitoring reserves, capital, and financial condition so promised benefits can actually be paid.', 'Solvency regulation = making sure claims get paid.', NULL),
('insurance_regulation', 'easy', 'The Wisconsin Insurance Security Fund (ch. 646) exists primarily to:', '["Protect policyholders when an insurer becomes insolvent","Subsidize premiums for low-income residents","Fund the operating budget of OCI","Guarantee producers'' commissions"]'::jsonb, 'Protect policyholders when an insurer becomes insolvent', 'Chapter 646 creates a backstop of last resort that helps pay covered claims and continue coverage when a member insurer is liquidated.', 'Security Fund = insolvency backstop of last resort.', 'Wisconsin'),
('insurance_regulation', 'medium', 'State rate regulation generally requires that insurance rates NOT be:', '["Excessive, inadequate, or unfairly discriminatory","Higher than the national average","Approved by policyholder vote","Identical across all insurers"]'::jsonb, 'Excessive, inadequate, or unfairly discriminatory', 'The classic regulatory standard for rates is that they be neither excessive nor inadequate and not unfairly discriminatory among insureds of the same class.', 'Rates: not excessive, not inadequate, not unfairly discriminatory.', NULL),
('insurance_regulation', 'medium', 'Under s. 631.20, before a life insurance policy form may be used in Wisconsin, it generally must be:', '["Filed with and approved by the commissioner","Approved by the National Association of Insurance Commissioners","Reviewed by the state legislature","Certified by an independent actuary hired by the policyholder"]'::jsonb, 'Filed with and approved by the commissioner', 'Wisconsin requires policy forms to be filed with OCI for approval before use, which lets the regulator screen out unfair or misleading contract language.', 'Policy forms are filed with and approved by OCI.', 'Wisconsin'),
('insurance_regulation', 'medium', 'Wisconsin''s policy readability requirements are intended to ensure that:', '["Policies are written in language an average purchaser can understand","Policies use formal legal terminology exclusively","All policies are limited to one page","Policies are drafted by licensed attorneys only"]'::jsonb, 'Policies are written in language an average purchaser can understand', 'Readability standards require plain, understandable policy language so consumers can grasp what they are buying.', 'Readability = plain language for the average buyer.', 'Wisconsin'),
('insurance_regulation', 'medium', 'Which insurer practice is an example of an unfair claims settlement practice?', '["Routinely misrepresenting policy provisions to avoid paying claims","Requesting reasonable documentation of a loss","Paying a claim promptly after receiving proof of loss","Investigating claims that show indicators of fraud"]'::jsonb, 'Routinely misrepresenting policy provisions to avoid paying claims', 'Misrepresenting coverage to claimants, failing to acknowledge communications, and refusing to pay without investigation are classic unfair claims practices; the other options are legitimate claim handling.', 'Lying about coverage to dodge claims = unfair claims practice.', NULL),
('insurance_regulation', 'easy', 'A Wisconsin policyholder who believes an insurer or intermediary has acted improperly may:', '["File a complaint with the Office of the Commissioner of Insurance","Complain only to the insurer''s board of directors","Do nothing unless a lawsuit is filed","Petition the federal insurance bureau"]'::jsonb, 'File a complaint with the Office of the Commissioner of Insurance', 'OCI accepts and investigates consumer complaints against insurers and intermediaries; insurers must give notice of this right. There is no federal insurance bureau with general jurisdiction.', 'Consumer complaints go to OCI.', 'Wisconsin'),
('insurance_regulation', 'medium', 'Premium funds an intermediary receives on behalf of an insurer must be:', '["Held in a fiduciary capacity and promptly remitted","Deposited into the intermediary''s personal account until month-end","Invested for the intermediary''s benefit until the premium is due","Returned to the client if not remitted within one year"]'::jsonb, 'Held in a fiduciary capacity and promptly remitted', 'Premiums are trust funds. Intermediaries may not commingle them with personal funds and must forward them promptly to the insurer.', 'Premiums are trust funds: no commingling, prompt remittance.', 'Wisconsin'),
('insurance_regulation', 'medium', 'An intermediary who tells a prospect that policy dividends are guaranteed by the insurer has committed:', '["Misrepresentation","Rebating","Coercion","Defamation"]'::jsonb, 'Misrepresentation', 'Dividends are never guaranteed. Falsely describing the terms, benefits, or dividends of a policy is misrepresentation under s. 628.34(1).', 'Dividends are never guaranteed - saying so is misrepresentation.', 'Wisconsin'),
('insurance_regulation', 'medium', 'Charging two insureds in the same actuarial class and with equal life expectancies different premiums for the same coverage is:', '["Unfair discrimination","Sound underwriting","Rebating","Twisting"]'::jsonb, 'Unfair discrimination', 'Unfair discrimination under s. 628.34(3) means treating members of the same class with essentially the same risk differently as to rates or benefits.', 'Same class, same risk, different rate = unfair discrimination.', 'Wisconsin'),
('insurance_regulation', 'hard', 'Which of the following is an unlawful inducement under s. 628.34?', '["Offering to refund part of the commission to the applicant as an incentive to buy","Explaining the insurer''s historical dividend performance","Delivering a buyer''s guide with the proposal","Quoting the insurer''s filed premium rate"]'::jsonb, 'Offering to refund part of the commission to the applicant as an incentive to buy', 'Giving the buyer anything of value not specified in the policy - including a share of the commission - is rebating, a prohibited inducement.', 'Kicking back commission to the buyer = rebating.', 'Wisconsin'),
('insurance_regulation', 'hard', 'Making false, maliciously critical statements about an insurer''s financial condition in order to injure its business is:', '["Defamation","Twisting","Boycott","Concealment"]'::jsonb, 'Defamation', 'Defamation is an unfair marketing practice involving false and malicious statements calculated to injure a person or company engaged in the insurance business.', 'Trashing an insurer with false statements = defamation.', 'Wisconsin'),
('insurance_regulation', 'easy', 'An advertisement that materially misstates the benefits, terms, or dividends of a life insurance policy is an example of:', '["False advertising","Permissible puffery","Controlled business","Fair disclosure"]'::jsonb, 'False advertising', 'Untrue, deceptive, or misleading statements in insurance advertising violate s. 628.34(1) and are prohibited.', 'Misleading ads = false advertising under s. 628.34.', 'Wisconsin'),
('insurance_regulation', 'hard', 'Boycott, coercion, and intimidation as unfair trade practices involve:', '["Using concerted action or threats to restrain trade in the insurance business","Charging rates below the filed schedule","Sharing commissions with licensed intermediaries","Offering free financial planning seminars"]'::jsonb, 'Using concerted action or threats to restrain trade in the insurance business', 'Section 628.34(4) prohibits agreements or threats intended to restrain competition or force the purchase or placement of insurance.', 'Boycott/coercion = restraining insurance trade by force or agreement.', 'Wisconsin'),
('insurance_regulation', 'medium', 'An applicant orally discloses a health condition to the intermediary, who fails to record it on the application. Under the rule that an agent''s knowledge binds the insurer:', '["The insurer is generally deemed to know what its intermediary knew","The applicant is automatically guilty of concealment","The policy is void from inception","The intermediary becomes personally liable for the claim amount"]'::jsonb, 'The insurer is generally deemed to know what its intermediary knew', 'Under agency principles reflected in s. 628.40, information given to the agent within the scope of the agency is imputed to the insurer.', 'What the agent knows, the insurer knows.', 'Wisconsin'),
('insurance_regulation', 'medium', 'Under the Fair Credit Reporting Act, before an insurer obtains a consumer report on an applicant, the applicant must:', '["Be notified that such a report may be requested","Provide fingerprints to the reporting agency","Pay for the report in advance","Waive all privacy rights in writing"]'::jsonb, 'Be notified that such a report may be requested', 'The FCRA requires that consumers be informed when a consumer report may be obtained in connection with an insurance application.', 'FCRA: tell the applicant a report may be pulled.', NULL),
('insurance_regulation', 'medium', 'If an insurer declines an application based on information in a consumer report, the FCRA requires the insurer to:', '["Tell the applicant and identify the reporting agency that furnished the report","Keep the source of the information confidential","Refund double the initial premium","Refer the applicant to another insurer"]'::jsonb, 'Tell the applicant and identify the reporting agency that furnished the report', 'On adverse action based on a consumer report, the consumer must be notified and given the name and address of the consumer reporting agency so they can dispute inaccuracies.', 'Adverse action = disclose the reporting agency to the applicant.', NULL),
('insurance_regulation', 'medium', 'An investigative consumer report differs from an ordinary consumer report because it:', '["Includes interviews with neighbors, friends, and associates about the consumer''s character and lifestyle","Contains only credit scores","Is prepared exclusively by the MIB","May be obtained without any notice to the consumer"]'::jsonb, 'Includes interviews with neighbors, friends, and associates about the consumer''s character and lifestyle', 'Investigative consumer reports gather information on character, general reputation, and mode of living through personal interviews, and they carry additional FCRA disclosure requirements.', 'Investigative report = personal interviews about character and lifestyle.', NULL),
('insurance_regulation', 'medium', 'Under 18 USC 1033, making material false statements or reports in connection with the business of insurance affecting interstate commerce is:', '["A federal crime","A civil matter left entirely to the states","Permitted if the insurer consents","Only an ethics violation"]'::jsonb, 'A federal crime', 'Section 1033 makes fraud and false statements in the business of insurance a federal criminal offense, punishable by fines and imprisonment.', '18 USC 1033 = federal insurance fraud crime.', NULL);
INSERT INTO public.questions (domain, difficulty, question, options, correct, explanation, know_this, state_specific) VALUES
('insurance_regulation', 'hard', 'Under 18 USC 1033, a person engaged in the business of insurance who embezzles or misappropriates funds of an insurer:', '["Has committed a federal crime punishable by fines and imprisonment","Faces only state administrative penalties","Is liable only if the insurer becomes insolvent","May settle the matter privately with the insurer"]'::jsonb, 'Has committed a federal crime punishable by fines and imprisonment', 'The federal fraud and false statements statutes (18 USC 1033-1034) criminalize embezzlement and willful misappropriation of insurer funds, in addition to any state penalties.', 'Embezzling insurer funds is a federal crime under 1033.', NULL),
('insurance_regulation', 'medium', 'Under federal do-not-call rules, a producer telemarketing life insurance generally may still call a consumer listed on the national registry when:', '["The consumer has an established business relationship with, or gave prior written consent to, the caller","The call is made from a personal cell phone","The producer limits the call to five minutes","The consumer''s number was obtained from a purchased lead list"]'::jsonb, 'The consumer has an established business relationship with, or gave prior written consent to, the caller', 'The national do-not-call registry has exceptions for established business relationships and for consumers who give express written permission to be called.', 'DNC exceptions: existing relationship or written consent.', NULL),
('insurance_regulation', 'hard', 'Federal telemarketing rules generally restrict sales calls to consumers to which hours (local time of the person called)?', '["8 a.m. to 9 p.m.","9 a.m. to 5 p.m.","7 a.m. to 11 p.m.","There are no time-of-day restrictions"]'::jsonb, '8 a.m. to 9 p.m.', 'Telemarketing sales calls may only be made between 8 a.m. and 9 p.m. local time at the called party''s location.', 'Telemarketing window: 8 a.m. - 9 p.m. local time.', NULL),
('insurance_regulation', 'medium', 'Under federal anti-money laundering rules, an insurer that detects a suspicious transaction involving a covered life product must file a suspicious activity report with:', '["FinCEN (the Financial Crimes Enforcement Network)","The state insurance commissioner only","The Federal Trade Commission","The Securities and Exchange Commission"]'::jsonb, 'FinCEN (the Financial Crimes Enforcement Network)', 'AML programs under the Bank Secrecy Act require insurers to report suspicious activity to FinCEN, the Treasury bureau that administers anti-money laundering rules.', 'Suspicious activity reports go to FinCEN.', NULL),
('insurance_regulation', 'hard', 'Which products are generally treated as "covered products" under federal anti-money laundering rules for insurers?', '["Permanent life insurance with cash value and annuity contracts","Term life insurance policies","Group life certificates","Credit life insurance"]'::jsonb, 'Permanent life insurance with cash value and annuity contracts', 'AML rules target products with investment or stored-value features that can be abused to launder money - cash value life insurance and annuities - not pure protection products like term or group life.', 'AML covered products = cash value life and annuities, not term.', NULL);
INSERT INTO public.questions (domain, difficulty, question, options, correct, explanation, know_this, state_specific) VALUES
('wisconsin_regulation', 'medium', 'Wisconsin law requires individual life policies to provide a grace period of at least 31 days. If the insured dies during the grace period:', '["The death claim is paid, less any premium due","The claim is denied because the premium was unpaid","Only the cash value is paid to the beneficiary","The policy is treated as never having existed"]'::jsonb, 'The death claim is paid, less any premium due', 'Coverage stays in force during the 31-day grace period; if death occurs then, the insurer pays the death benefit minus the overdue premium.', 'Death in the grace period: benefit paid minus unpaid premium.', 'Wisconsin'),
('wisconsin_regulation', 'medium', 'How does Wisconsin''s free-look period for a life policy purchased as a replacement compare with the free look on an ordinary new policy?', '["It is longer - 20 to 30 days instead of the standard 10 days","It is the same 10 days","It is shorter, because the buyer already owns coverage","Replacement policies have no free-look period"]'::jsonb, 'It is longer - 20 to 30 days instead of the standard 10 days', 'Wisconsin gives buyers of replacement life policies an extended free look of 20 to 30 days, versus the standard 10-day free look on a new individual policy, because replacement carries extra risk to the consumer.', 'WI free look: 10 days new, 20-30 days on replacement.', 'Wisconsin'),
('wisconsin_regulation', 'medium', 'After a Wisconsin life insurance policy has been in force during the insured''s lifetime for two years from issue, the insurer generally may contest the policy only for:', '["Nonpayment of premiums","Any misstatement in the application","Errors made by the intermediary","Changes in the insured''s health"]'::jsonb, 'Nonpayment of premiums', 'The incontestability rule bars the insurer from voiding the policy over application misstatements after two years; nonpayment of premium remains a basis for termination.', 'After 2 years, only nonpayment can defeat the policy.', 'Wisconsin'),
('wisconsin_regulation', 'easy', 'If an insured''s age was misstated on a Wisconsin life application and the error is discovered at death, the insurer will generally:', '["Adjust the death benefit to the amount the premium would have purchased at the correct age","Void the policy and refund premiums","Pay the full face amount regardless","Deny the claim as fraudulent"]'::jsonb, 'Adjust the death benefit to the amount the premium would have purchased at the correct age', 'Misstatement of age is not grounds to void coverage; benefits are simply recalculated based on what the premiums paid would have bought at the true age.', 'Wrong age = adjusted benefit, not a denied claim.', 'Wisconsin'),
('wisconsin_regulation', 'medium', 'To recommend and sell variable life insurance in Wisconsin, an intermediary must hold:', '["A Wisconsin life insurance license plus federal securities registration","Only a Wisconsin life insurance license","Only a securities registration","A property and casualty license with a variable endorsement"]'::jsonb, 'A Wisconsin life insurance license plus federal securities registration', 'Variable products are securities as well as insurance, so selling them requires both a state life license and registration with FINRA/SEC.', 'Variable products need both a life license and securities registration.', 'Wisconsin'),
('wisconsin_regulation', 'medium', 'Under Wisconsin law (s. 632.47), a policyowner who wishes to assign a life insurance policy:', '["May do so without the insurer''s consent, but the insurer must receive written notice to be bound","Must obtain the insurer''s prior approval","Must obtain the beneficiary''s consent even if the designation is revocable","May not assign a life policy under any circumstances"]'::jsonb, 'May do so without the insurer''s consent, but the insurer must receive written notice to be bound', 'Life policies are freely assignable by the owner; the insurer''s consent is not required, but it is not bound by an assignment until it receives written notice.', 'Assignment needs notice to the insurer, not its consent.', 'Wisconsin'),
('wisconsin_regulation', 'easy', 'Under Wisconsin law, a policyowner who has named a revocable beneficiary may change that designation:', '["At any time without the beneficiary''s consent","Only with the beneficiary''s written consent","Only on a policy anniversary","Only with the commissioner''s approval"]'::jsonb, 'At any time without the beneficiary''s consent', 'A revocable beneficiary has only an expectancy; the owner retains full rights to change the designation. Only an irrevocable beneficiary''s consent is required for changes affecting that beneficiary.', 'Revocable beneficiary = owner can change anytime.', 'Wisconsin'),
('wisconsin_regulation', 'hard', 'Wisconsin''s timely payment of claims statute (s. 628.46) generally provides that claims:', '["Must be paid promptly, and overdue claims bear interest","May be paid whenever the insurer completes its annual audit","Are payable only after a court judgment","May be delayed indefinitely while premiums are refunded"]'::jsonb, 'Must be paid promptly, and overdue claims bear interest', 'Section 628.46 requires prompt payment of claims and imposes interest on claims that become overdue, discouraging insurers from sitting on valid claims.', 's. 628.46: pay claims promptly or owe interest.', 'Wisconsin'),
('wisconsin_regulation', 'easy', 'Under Wisconsin replacement regulation, a "replacement" occurs when a new life policy is purchased and an existing policy is:', '["Lapsed, surrendered, or materially reduced in value as a result","Kept fully in force unchanged","Reviewed by the policyowner","Transferred to a family member"]'::jsonb, 'Lapsed, surrendered, or materially reduced in value as a result', 'Replacement rules are triggered when the purchase of new coverage causes existing coverage to be lapsed, surrendered, converted, or otherwise reduced in value.', 'Replacement = new policy causes old policy to lapse or shrink.', 'Wisconsin'),
('wisconsin_regulation', 'medium', 'When a Wisconsin intermediary recommends replacing an existing life policy, the intermediary must:', '["Provide the applicant with required written disclosure comparing the existing and proposed policies","Cancel the existing policy on the client''s behalf first","Obtain the existing insurer''s permission","Guarantee the new policy will outperform the old one"]'::jsonb, 'Provide the applicant with required written disclosure comparing the existing and proposed policies', 'Replacement rules require written disclosure so the consumer can compare old and new coverage before giving up existing protection; producers never cancel policies for clients or guarantee performance.', 'Replacement = written comparison disclosure to the applicant.', 'Wisconsin'),
('wisconsin_regulation', 'hard', 'A Wisconsin intermediary who repeatedly replaces clients'' existing policies primarily to generate new first-year commissions is engaged in:', '["Churning","Rebating","Coercion","Defamation"]'::jsonb, 'Churning', 'Churning is the practice of replacing policies to generate commissions rather than to benefit the client, and it is an unfair marketing practice.', 'Churning = replacing policies to farm commissions.', 'Wisconsin'),
('wisconsin_regulation', 'medium', 'In a Wisconsin life insurance replacement transaction, the existing insurer is protected by the requirement that it:', '["Be notified of the proposed replacement","Approve the new policy''s premium rate","Receive part of the new commission","Countersign the new application"]'::jsonb, 'Be notified of the proposed replacement', 'Replacement rules require notification to the existing insurer, giving it an opportunity to conserve the business and the policyowner a chance to reconsider.', 'Replacement rules make sure the old insurer is notified.', 'Wisconsin'),
('wisconsin_regulation', 'medium', 'In a Wisconsin life insurance solicitation, the buyer''s guide and policy summary are designed to be delivered:', '["Before or at the time the policy is delivered, so the buyer can evaluate the purchase","Only if the buyer asks for them in writing","One year after purchase","Only for policies over a certain face amount"]'::jsonb, 'Before or at the time the policy is delivered, so the buyer can evaluate the purchase', 'Wisconsin''s life disclosure rules require consumers to receive a buyer''s guide and policy summary in connection with the sale so they can make an informed decision.', 'Buyer''s guide + policy summary = required sale disclosures.', 'Wisconsin'),
('wisconsin_regulation', 'medium', 'A Wisconsin life insurance policy summary primarily contains:', '["Premium, cash value, and benefit figures specific to the policy being proposed","General education about all types of life insurance","The insurer''s full audited financial statements","A list of every producer appointed by the insurer"]'::jsonb, 'Premium, cash value, and benefit figures specific to the policy being proposed', 'The policy summary presents the numbers for the specific proposed policy; the buyer''s guide is the generic educational piece.', 'Policy summary = this policy''s numbers; buyer''s guide = general education.', 'Wisconsin'),
('wisconsin_regulation', 'medium', 'Under Wisconsin''s life insurance illustration rules, an illustration must:', '["Clearly distinguish guaranteed elements from non-guaranteed elements","Show only the most optimistic projection","Omit the guaranteed values to avoid confusion","Be signed by the commissioner"]'::jsonb, 'Clearly distinguish guaranteed elements from non-guaranteed elements', 'Illustration rules exist to prevent consumers from mistaking projected, non-guaranteed values for promises; guaranteed and non-guaranteed elements must be clearly separated and labeled.', 'Illustrations must separate guaranteed from projected values.', 'Wisconsin'),
('wisconsin_regulation', 'hard', 'Wisconsin''s life insurance cost disclosure rules help consumers compare similar policies using:', '["Cost comparison indexes such as the surrender cost and net payment cost indexes","The insurer''s advertising budget","The producer''s commission schedule","The number of policies the insurer has sold"]'::jsonb, 'Cost comparison indexes such as the surrender cost and net payment cost indexes', 'Standardized cost indexes let a buyer compare the relative cost of similar policies; lower index values generally indicate lower cost.', 'Cost comparison = surrender cost and net payment indexes.', 'Wisconsin'),
('wisconsin_regulation', 'hard', 'A Wisconsin intermediary markets a cash value life policy strictly as a "retirement savings plan" and never identifies it as life insurance. This practice is:', '["Prohibited as misleading - solicitations must make clear the product is life insurance","Permitted if the policy has strong cash value growth","Permitted for clients over age 60","Required for policies sold in the workplace"]'::jsonb, 'Prohibited as misleading - solicitations must make clear the product is life insurance', 'Disclosure rules require that the consumer understand the product being solicited is life insurance; disguising it as a savings or retirement program is deceptive.', 'You must tell the buyer it is life insurance.', 'Wisconsin'),
('wisconsin_regulation', 'medium', 'Which of the following is NOT an unlawful inducement in Wisconsin?', '["Paying policy dividends to policyholders as declared by the insurer","Refunding part of the commission to the buyer","Giving a buyer valuable consideration not specified in the policy","Promising employment in exchange for a purchase"]'::jsonb, 'Paying policy dividends to policyholders as declared by the insurer', 'Dividends declared under the policy''s own terms are a contractual benefit, not a rebate; the other choices are prohibited inducements.', 'Declared dividends are not rebates.', 'Wisconsin'),
('wisconsin_regulation', 'medium', 'Under Wisconsin advertising rules for life insurance, the insurer is responsible for ensuring its advertisements are:', '["Truthful and not misleading in fact or by implication","Reviewed by the NAIC before publication","Limited to print media","Written only by licensed intermediaries"]'::jsonb, 'Truthful and not misleading in fact or by implication', 'Insurers are accountable for their advertising content, which must be accurate and must not mislead consumers directly or by implication.', 'Insurers own their ads: truthful, never misleading.', 'Wisconsin'),
('wisconsin_regulation', 'medium', 'Before recommending an annuity to a Wisconsin consumer, an intermediary must collect suitability information including:', '["Age, income, financial objectives, liquidity needs, and risk tolerance","Only the consumer''s age and zip code","The consumer''s voting registration","A physician''s statement of good health"]'::jsonb, 'Age, income, financial objectives, liquidity needs, and risk tolerance', 'Wisconsin''s annuity suitability rule (s. 628.347) requires gathering the consumer''s financial status, tax status, objectives, and other relevant profile information before making a recommendation.', 'Suitability = know the customer before recommending an annuity.', 'Wisconsin')
INSERT INTO public.questions (domain, difficulty, question, options, correct, explanation, know_this, state_specific) VALUES
('wisconsin_regulation', 'easy', 'Under Wisconsin''s annuity suitability rule, before recommending an annuity an intermediary must have:', '["Reasonable grounds to believe the recommendation is suitable for that consumer","A guarantee that the annuity will outperform the market","The consumer''s power of attorney","Approval from the consumer''s accountant"]'::jsonb, 'Reasonable grounds to believe the recommendation is suitable for that consumer', 'The core suitability standard is that the producer must reasonably believe, based on the consumer''s disclosed profile, that the recommended annuity suits that consumer''s needs and objectives.', 'Annuity standard: reasonable grounds the sale is suitable.', 'Wisconsin'),
('wisconsin_regulation', 'hard', 'Under s. 628.347, insurers that sell annuities in Wisconsin must:', '["Establish a supervision system reasonably designed to ensure recommendations are suitable","Guarantee a minimum rate of return on every annuity","Approve every sale personally through the company president","Refuse all annuity sales to consumers over age 75"]'::jsonb, 'Establish a supervision system reasonably designed to ensure recommendations are suitable', 'The suitability statute puts obligations on insurers as well as producers: insurers must maintain a system to supervise recommendations and achieve compliance.', 'Insurers must supervise annuity suitability, not just producers.', 'Wisconsin'),
('wisconsin_regulation', 'hard', 'Under Wisconsin''s annuity suitability rules, sales made in compliance with comparable FINRA suitability requirements:', '["Generally satisfy the state suitability requirement (a safe harbor)","Are exempt from all Wisconsin insurance law","Are automatically unsuitable","Require a second review by OCI before issue"]'::jsonb, 'Generally satisfy the state suitability requirement (a safe harbor)', 'The rule includes a safe harbor: recommendations handled under FINRA''s comparable suitability standards are deemed to satisfy the state requirement.', 'FINRA-compliant annuity sales get a suitability safe harbor.', 'Wisconsin'),
('wisconsin_regulation', 'medium', 'Before selling annuity products in Wisconsin, an intermediary must:', '["Complete required annuity training in addition to holding a life license","Only hold a securities registration","Post a surety bond with OCI","Obtain a separate annuity-only license"]'::jsonb, 'Complete required annuity training in addition to holding a life license', 'Section 628.347 imposes a producer training requirement for annuity sales on top of ordinary licensure; there is no separate annuity license or bond requirement.', 'Selling annuities requires annuity training, not a new license.', 'Wisconsin'),
('wisconsin_regulation', 'hard', 'Under Wisconsin''s annuity suitability rules, an intermediary may NOT:', '["Dissuade a consumer from answering suitability questions truthfully or from cooperating with an insurer''s review","Ask a consumer about liquidity needs","Document the basis for a recommendation","Decline to recommend a product that appears unsuitable"]'::jsonb, 'Dissuade a consumer from answering suitability questions truthfully or from cooperating with an insurer''s review', 'The rule expressly prohibits discouraging consumers from providing accurate suitability information, filing complaints, or cooperating with investigations.', 'Never coach a client to fudge suitability answers.', 'Wisconsin'),
('wisconsin_regulation', 'medium', 'Stranger-originated life insurance (STOLI) is best described as:', '["A policy initiated primarily for the benefit of an investor who lacks insurable interest in the insured","Any life policy later sold in a legitimate life settlement","A policy purchased by a spouse on the other spouse","Group coverage sponsored by an employer"]'::jsonb, 'A policy initiated primarily for the benefit of an investor who lacks insurable interest in the insured', 'STOLI schemes originate coverage at the outset for the benefit of strangers, evading the insurable interest requirement that must exist at policy inception.', 'STOLI = policy born for a stranger investor''s benefit.', 'Wisconsin'),
('wisconsin_regulation', 'medium', 'Under s. 632.69, stranger-originated life insurance transactions in Wisconsin are:', '["Prohibited","Permitted with the insured''s consent","Permitted for face amounts under a set limit","Encouraged as a source of policy liquidity"]'::jsonb, 'Prohibited', 'Wisconsin''s life settlements law expressly prohibits STOLI because it manufactures policies for investors without insurable interest, undermining the purpose of life insurance.', 'STOLI is illegal in Wisconsin.', 'Wisconsin'),
('wisconsin_regulation', 'medium', 'In a Wisconsin life settlement transaction, the life settlement broker represents:', '["The policyowner selling the policy","The purchasing investor","The insurance company that issued the policy","The state of Wisconsin"]'::jsonb, 'The policyowner selling the policy', 'A settlement broker owes duties to the owner and negotiates on the owner''s behalf; the provider is the party acquiring the policy.', 'Settlement broker works for the selling owner; provider buys.', 'Wisconsin'),
('wisconsin_regulation', 'medium', 'Under s. 632.69, persons acting as life settlement providers or brokers in Wisconsin must:', '["Be licensed by the commissioner","Register only with FINRA","Hold a real estate license","Post their contracts on a public exchange"]'::jsonb, 'Be licensed by the commissioner', 'Wisconsin''s life settlements statute requires providers and brokers to obtain licenses from OCI before transacting settlement business.', 'Life settlement providers and brokers need OCI licenses.', 'Wisconsin'),
('wisconsin_regulation', 'medium', 'The Wisconsin Insurance Security Fund obtains the money it uses to protect policyholders of insolvent insurers primarily from:', '["Assessments on member insurers doing business in Wisconsin","State income tax revenue","Voluntary policyholder donations","Federal grants"]'::jsonb, 'Assessments on member insurers doing business in Wisconsin', 'The fund is financed by assessing solvent member insurers when an insolvency occurs; it is an industry-funded backstop, not a tax-funded program.', 'Security Fund money comes from insurer assessments.', 'Wisconsin'),
('wisconsin_regulation', 'hard', 'When soliciting life insurance in Wisconsin, an intermediary''s use of the Insurance Security Fund''s existence as a selling point is:', '["Prohibited","Required in every proposal","Permitted with the insurer''s consent","Permitted only in written advertisements"]'::jsonb, 'Prohibited', 'Producers may not use the existence of the guaranty-type Security Fund to induce sales, because doing so misleadingly downplays the importance of insurer solvency.', 'Never sell insurance by advertising the Security Fund.', 'Wisconsin'),
('wisconsin_regulation', 'medium', 'The Wisconsin Insurance Security Fund generally protects:', '["Wisconsin resident policyholders and beneficiaries of insolvent member insurers","Insurance company shareholders against investment losses","Producers whose commissions go unpaid","Any policyholder anywhere in the United States"]'::jsonb, 'Wisconsin resident policyholders and beneficiaries of insolvent member insurers', 'The fund''s protection runs to Wisconsin residents with claims against liquidated member insurers - not to shareholders, producers, or residents of other states.', 'The Fund protects WI policyholders, not shareholders or agents.', 'Wisconsin'),
('wisconsin_regulation', 'medium', 'The purpose of the Interstate Insurance Product Regulation Compact (s. 601.58) is to:', '["Provide a single point of filing with uniform national standards for certain insurance products","Replace state insurance regulation with federal regulation","Set uniform commission rates for producers","Merge all state guaranty funds"]'::jsonb, 'Provide a single point of filing with uniform national standards for certain insurance products', 'The compact lets insurers file certain product forms once with the compact commission under uniform standards instead of filing separately in every member state.', 'Compact = one filing, uniform standards, many states.', 'Wisconsin'),
('wisconsin_regulation', 'hard', 'The Interstate Insurance Product Regulation Compact applies to which product lines?', '["Life insurance, annuities, disability income, and long-term care","Auto and homeowners insurance","Workers compensation","Commercial liability insurance"]'::jsonb, 'Life insurance, annuities, disability income, and long-term care', 'The compact''s uniform standards cover the asset-based and individually underwritten lines: life, annuity, disability income, and long-term care products.', 'Compact lines: life, annuities, DI, LTC.', 'Wisconsin'),
('wisconsin_regulation', 'medium', 'Under Wisconsin''s insurance privacy law (s. 610.70), insurers that collect personal information about applicants must:', '["Provide notice of their information practices and allow individuals to access and correct their information","Sell the information only to affiliated companies","Destroy all records within one year","Publish applicant information in their annual report"]'::jsonb, 'Provide notice of their information practices and allow individuals to access and correct their information', 'Wisconsin''s privacy provisions require notice of information practices and give consumers rights to see and correct recorded personal information held by insurers.', 'Privacy law: notice, access, and correction rights.', 'Wisconsin')
INSERT INTO public.questions (domain, difficulty, question, options, correct, explanation, know_this, state_specific) VALUES
('policy_provisions', 'easy', 'When a life insurance policy is owned by someone other than the insured, who has the right to name beneficiaries and take policy loans?', '["The policyowner","The insured","The primary beneficiary","The producer who sold the policy"]'::jsonb, 'The policyowner', 'Ownership rights - naming beneficiaries, assigning the policy, borrowing against cash value - belong to the policyowner, even in third-party ownership where the owner is not the insured.', 'Policy rights follow the owner, not the insured.', NULL),
('policy_provisions', 'medium', 'A policyowner assigns a life policy to a bank as security for a loan, with the bank''s interest limited to the loan balance. This is a(n):', '["Collateral assignment","Absolute assignment","Beneficiary designation","Ownership transfer at death"]'::jsonb, 'Collateral assignment', 'A collateral assignment gives the assignee a limited, temporary interest as security for a debt; an absolute assignment transfers all ownership rights permanently.', 'Collateral = temporary security; absolute = full transfer.', NULL),
('policy_provisions', 'medium', 'Under the modifications provision of a life policy, changes to the contract are valid only if made:', '["In writing by an authorized officer of the insurer","Verbally by the selling producer","By the policyowner writing on the policy","By the beneficiary with two witnesses"]'::jsonb, 'In writing by an authorized officer of the insurer', 'Only specified insurer officers can modify or waive policy terms, and changes must be in writing; producers have no authority to alter the contract.', 'Only an insurer officer can change the contract - never the agent.', NULL),
('policy_provisions', 'medium', 'Compared with paying an annual premium, paying the same policy''s premium monthly generally results in:', '["A higher total outlay for the year","A lower total outlay for the year","Exactly the same total cost","A larger death benefit"]'::jsonb, 'A higher total outlay for the year', 'More frequent payment modes carry service charges and lost interest, so monthly or quarterly modes cost more in total than a single annual payment.', 'More frequent premium mode = higher total cost.', NULL),
('policy_provisions', 'medium', 'The automatic premium loan provision is designed to:', '["Pay an overdue premium from the policy''s cash value to prevent lapse","Increase the death benefit each year","Refund premiums if the insured stays healthy","Convert the policy to term insurance"]'::jsonb, 'Pay an overdue premium from the policy''s cash value to prevent lapse', 'If elected, the APL provision borrows automatically from cash value to cover an unpaid premium at the end of the grace period, keeping coverage in force.', 'APL = cash value automatically pays a missed premium.', NULL),
('policy_provisions', 'hard', 'When a lapsed life policy is reinstated, the incontestability clause generally:', '["Applies anew to statements made in the reinstatement application","Never applies again","Is permanently waived by the insurer","Extends to ten years"]'::jsonb, 'Applies anew to statements made in the reinstatement application', 'Reinstatement requires fresh evidence of insurability, and a new contestable period typically applies to the statements made in the reinstatement application.', 'Reinstatement restarts contestability for the new statements.', NULL),
('policy_provisions', 'medium', 'In the absence of fraud, statements made by an applicant on a life insurance application are considered:', '["Representations","Warranties","Guarantees","Endorsements"]'::jsonb, 'Representations', 'Application statements are treated as representations - true to the best of the applicant''s knowledge - rather than warranties, which would have to be literally true.', 'Application answers = representations, not warranties.', NULL),
('policy_provisions', 'medium', 'Which of the following is a common life insurance policy exclusion?', '["Death from war or military conflict","Death from cancer","Death from heart disease","Death occurring in a hospital"]'::jsonb, 'Death from war or military conflict', 'Typical exclusions include war, aviation (other than fare-paying passenger), and hazardous occupations or hobbies; deaths from ordinary illness are covered.', 'Classic exclusions: war, aviation, hazardous activities.', NULL),
('policy_provisions', 'hard', 'The primary reason an applicant might ask to backdate a life insurance policy is to:', '["Obtain a lower premium based on an earlier issue age","Extend the free-look period","Avoid the medical exam","Shorten the grace period"]'::jsonb, 'Obtain a lower premium based on an earlier issue age', 'Backdating (typically limited to a few months) lets the applicant "save age" - the policy is priced as if issued at the younger age, in exchange for paying premium back to the earlier date.', 'Backdating = save age, lower premium.', NULL),
('policy_provisions', 'easy', 'If the primary beneficiary dies before the insured and no changes are made, the death benefit is paid to the:', '["Contingent beneficiary","Insured''s creditors","State of residence","Producer of record"]'::jsonb, 'Contingent beneficiary', 'The contingent (secondary) beneficiary receives the proceeds if the primary beneficiary predeceases the insured; the estate takes only if no named beneficiary survives.', 'No living primary? Proceeds go to the contingent.', NULL),
('policy_provisions', 'medium', 'A beneficiary designation of "my children, per stirpes" means that if one child predeceases the insured, that child''s share:', '["Passes to that child''s own descendants","Is divided among the surviving children","Reverts to the insured''s estate","Is forfeited to the insurer"]'::jsonb, 'Passes to that child''s own descendants', 'Per stirpes ("by the branch") sends a deceased beneficiary''s share down to their descendants; per capita divides proceeds only among surviving named beneficiaries.', 'Per stirpes = a dead child''s share flows to their kids.', NULL),
('policy_provisions', 'medium', 'Naming a minor child directly as a life insurance beneficiary can be problematic because:', '["Insurers generally cannot pay proceeds directly to a minor, delaying payment until a guardian or trust is in place","Minors are prohibited from ever receiving insurance money","The policy becomes void","The premium doubles"]'::jsonb, 'Insurers generally cannot pay proceeds directly to a minor, delaying payment until a guardian or trust is in place', 'Minors lack legal capacity to receive and manage proceeds, so payment usually waits for a court-appointed guardian or should be routed through a trust or custodian arrangement.', 'Minor beneficiary = use a trust or guardian, or payment stalls.', NULL),
('policy_provisions', 'medium', 'If a policyowner names an irrevocable beneficiary, the owner may later:', '["Change the designation only with that beneficiary''s written consent","Change the designation freely at any time","Cancel the beneficiary''s interest by notifying the insurer","Ignore the designation when taking policy loans that impair the beneficiary''s interest"]'::jsonb, 'Change the designation only with that beneficiary''s written consent', 'An irrevocable beneficiary has a vested interest: the owner cannot change the designation or exercise rights that impair it without the beneficiary''s consent.', 'Irrevocable beneficiary = vested rights, consent required.', NULL),
('policy_provisions', 'hard', 'Under a common disaster clause, if the insured and primary beneficiary die in the same accident and order of death cannot be determined, proceeds are paid as though:', '["The primary beneficiary died first","The insured died first","Both survived","The state inherits the proceeds"]'::jsonb, 'The primary beneficiary died first', 'The common disaster provision (reflecting the Uniform Simultaneous Death Act) presumes the beneficiary predeceased the insured, so proceeds pass to contingent beneficiaries rather than through the primary beneficiary''s estate.', 'Common disaster: assume the beneficiary died first.', NULL),
('policy_provisions', 'hard', 'A spendthrift clause in a life insurance settlement arrangement is designed to:', '["Protect proceeds held by the insurer from the beneficiary''s creditors","Limit the insured''s spending during life","Prevent the policyowner from surrendering the policy","Reduce the premium for thrifty policyowners"]'::jsonb, 'Protect proceeds held by the insurer from the beneficiary''s creditors', 'When proceeds are paid under an installment option, a spendthrift clause shields amounts still held by the insurer from claims of the beneficiary''s creditors and from assignment by the beneficiary.', 'Spendthrift clause shields proceeds from the beneficiary''s creditors.', NULL),
('policy_provisions', 'medium', 'A children''s term rider on a parent''s life policy typically:', '["Covers all eligible children for one premium and is convertible to permanent coverage without evidence of insurability","Covers only the firstborn child","Requires a separate medical exam for each child","Terminates the parent''s coverage when a child reaches majority"]'::jsonb, 'Covers all eligible children for one premium and is convertible to permanent coverage without evidence of insurability', 'Children''s term riders cover each eligible child (including later-born children) under one rider premium and usually allow conversion to individual permanent coverage at a specified age without proving insurability.', 'Child rider: one premium, all kids, convertible without evidence.', NULL),
('policy_provisions', 'medium', 'Under the interest-only settlement option, the insurer:', '["Retains the death benefit and pays the beneficiary periodic interest earnings","Pays the full proceeds immediately","Pays equal installments until proceeds are exhausted","Purchases an annuity for the beneficiary automatically"]'::jsonb, 'Retains the death benefit and pays the beneficiary periodic interest earnings', 'With interest only, the principal stays with the insurer and the beneficiary receives interest payments, with the principal paid out later under another option or on demand.', 'Interest only: insurer keeps principal, pays the interest.', NULL),
('policy_provisions', 'medium', 'Under the fixed-period settlement option, the amount of each installment is determined primarily by:', '["The length of the period selected and the amount of proceeds","The beneficiary''s age and health","The insured''s final medical bills","The producer''s commission rate"]'::jsonb, 'The length of the period selected and the amount of proceeds', 'In a fixed-period option the proceeds plus interest are spread evenly over the chosen period - a longer period means smaller payments. The beneficiary''s life expectancy is irrelevant.', 'Fixed period: pick the years, the math sets the payment.', NULL),
('policy_provisions', 'hard', 'A life income with period certain settlement option guarantees:', '["Income for the beneficiary''s lifetime, with payments continuing to another payee if the beneficiary dies during the certain period","Income for a fixed period only, regardless of survival","A lump sum after ten years","That total payments will never exceed the face amount"]'::jsonb, 'Income for the beneficiary''s lifetime, with payments continuing to another payee if the beneficiary dies during the certain period', 'Life income with period certain pays as long as the beneficiary lives; if death occurs within the guaranteed period, payments continue to a contingent payee for the rest of that period.', 'Life income w/ period certain = lifetime income plus a guarantee window.', NULL),
('policy_provisions', 'easy', 'A policyowner who elects the cash surrender nonforfeiture option receives the cash value and:', '["All coverage ends","Coverage continues at a reduced amount","Coverage continues as term insurance","Premiums are waived"]'::jsonb, 'All coverage ends', 'Surrendering for cash terminates the contract entirely; the other nonforfeiture options (reduced paid-up, extended term) are the ones that continue some coverage.', 'Cash surrender = money now, coverage gone.', NULL)
INSERT INTO public.questions (domain, difficulty, question, options, correct, explanation, know_this, state_specific) VALUES
('policy_provisions', 'medium', 'Under the reduced paid-up nonforfeiture option, the policyowner receives:', '["A smaller amount of the same type of permanent coverage with no further premiums due","The same face amount for a shorter time","A refund of all premiums paid","Term coverage equal to the original face amount"]'::jsonb, 'A smaller amount of the same type of permanent coverage with no further premiums due', 'Reduced paid-up uses the cash value as a single premium to buy a reduced face amount of the same kind of permanent insurance, fully paid up for life.', 'Reduced paid-up: smaller face, same policy type, no more premiums.', NULL),
('policy_provisions', 'hard', 'If a policyowner stops paying premiums and never elects a nonforfeiture option, most life policies automatically apply:', '["The extended term option","The cash surrender option","The reduced paid-up option","The one-year term dividend option"]'::jsonb, 'The extended term option', 'Extended term - using the cash value to buy term coverage for the full face amount - is typically the automatic nonforfeiture option when the owner makes no election.', 'Extended term is usually the automatic nonforfeiture default.', NULL),
('policy_provisions', 'medium', 'If a policy loan is outstanding when the insured dies, the insurer will:', '["Deduct the loan balance plus accrued interest from the death benefit","Deny the death claim","Bill the beneficiary for the loan","Cancel the loan with no effect on proceeds"]'::jsonb, 'Deduct the loan balance plus accrued interest from the death benefit', 'Policy loans need never be repaid during life, but any unpaid loan and interest reduce the proceeds payable at death (or the cash value at surrender).', 'Unpaid loans come out of the death benefit.', NULL),
('policy_provisions', 'medium', 'A withdrawal (partial surrender) from a universal life policy generally:', '["Reduces the cash value and may reduce the death benefit","Must be repaid with interest","Has no effect on the policy","Converts the policy to term insurance"]'::jsonb, 'Reduces the cash value and may reduce the death benefit', 'Unlike a loan, a withdrawal permanently removes money from the policy, lowering cash value and typically the death benefit; it is not repaid.', 'UL withdrawal shrinks cash value and death benefit - no repayment.', NULL),
('policy_provisions', 'easy', 'The dividend option that uses each dividend to buy additional temporary coverage for one year is the:', '["One-year term option","Paid-up additions option","Cash option","Premium reduction option"]'::jsonb, 'One-year term option', 'Under the one-year term (fifth dividend) option, dividends purchase one-year term insurance, temporarily increasing the total death benefit.', 'Fifth dividend option = dividends buy 1-year term.', NULL),
('policy_provisions', 'medium', 'When dividends are left with the insurer to accumulate at interest, the interest earned is:', '["Taxable as income in the year credited","Always income-tax free","Taxed only at surrender","Deducted from the death benefit"]'::jsonb, 'Taxable as income in the year credited', 'Dividends themselves are a return of premium and not taxable, but interest the insurer credits on accumulated dividends is currently taxable income.', 'Dividends tax-free; interest on dividends taxable.', NULL),
('policy_provisions', 'medium', 'The payor benefit rider on a juvenile life policy provides that:', '["Premiums are waived if the adult premium payor dies or becomes disabled before the child reaches a stated age","The child may skip premiums after age 18","The death benefit doubles if the payor dies","The policy converts to an annuity"]'::jsonb, 'Premiums are waived if the adult premium payor dies or becomes disabled before the child reaches a stated age', 'The payor rider protects a child''s policy by waiving premiums when the paying parent or guardian dies or is disabled, until the child reaches the age specified.', 'Payor rider: parent dies or disabled, child''s premiums waived.', NULL),
('policy_provisions', 'medium', 'The accidental death (double indemnity) rider pays its additional benefit only when death:', '["Results from an accident and occurs within a period specified in the rider","Occurs from any cause before age 65","Occurs while the insured is at work","Results from illness diagnosed after issue"]'::jsonb, 'Results from an accident and occurs within a period specified in the rider', 'The rider multiplies the benefit (often 2x) only for accidental death occurring within a stated time after the injury, and typically expires at a specified age.', 'Double indemnity = accidental death within the stated window.', NULL),
('policy_provisions', 'medium', 'A return of premium rider on a term policy is typically structured as:', '["Increasing term insurance equal to the premiums paid to date","A savings account held by the producer","A dividend accumulation","A decreasing term rider"]'::jsonb, 'Increasing term insurance equal to the premiums paid to date', 'The rider effectively adds increasing term coverage so that, at death within the term, the beneficiary receives the face amount plus an amount equal to premiums paid.', 'Return of premium = built-in increasing term rider.', NULL),
('policy_provisions', 'medium', 'When an insured collects an accelerated (living) benefit for terminal illness, the amount payable to the beneficiary at death is:', '["Reduced by the accelerated amount paid","Unchanged","Increased by interest on the accelerated amount","Forfeited entirely"]'::jsonb, 'Reduced by the accelerated amount paid', 'Accelerated benefits are an advance of the policy''s own death benefit, so whatever is paid during life (plus any charges) reduces what the beneficiary later receives.', 'Living benefits are an advance on the death benefit.', NULL),
('life_types', 'easy', 'Under an annually renewable term (ART) policy, the death benefit and premium behave how?', '["The death benefit stays level while the premium increases at each renewal","Both stay level for life","The premium stays level while the death benefit decreases","Both decrease each year"]'::jsonb, 'The death benefit stays level while the premium increases at each renewal', 'ART renews each year at the insured''s attained age, so the premium rises annually while the face amount remains constant.', 'ART: level face, premium climbs every year.', NULL),
('life_types', 'medium', 'A 20-year level premium term policy keeps premiums level by:', '["Charging more than the annual cost of insurance in early years and less in later years","Investing premiums in a separate account","Reducing the death benefit each year","Charging the attained-age rate every year"]'::jsonb, 'Charging more than the annual cost of insurance in early years and less in later years', 'Level premium term averages the increasing mortality cost over the term - early overpayments offset later underpayments - producing a level outlay.', 'Level term = mortality cost averaged over the period.', NULL),
('life_types', 'medium', 'The renewability feature of a term policy allows the insured to:', '["Continue coverage for another term without new evidence of insurability, at a premium based on attained age","Continue coverage at the original issue-age premium","Convert to an annuity","Extend coverage at no cost"]'::jsonb, 'Continue coverage for another term without new evidence of insurability, at a premium based on attained age', 'Renewable term guarantees the right to renew without a new exam, but each renewal is priced at the insured''s current (attained) age.', 'Renewable: no new exam, but attained-age pricing.', NULL),
('life_types', 'medium', 'The conversion privilege in a term policy permits the policyowner to:', '["Exchange the term policy for permanent coverage without evidence of insurability","Exchange the policy for a larger term policy at no cost","Transfer the policy to another insured","Convert cash value into paid-up additions"]'::jsonb, 'Exchange the term policy for permanent coverage without evidence of insurability', 'Convertible term lets the owner move to whole life or another permanent plan without proving insurability, typically at attained-age rates.', 'Convertible term: switch to permanent, no new underwriting.', NULL),
('life_types', 'medium', 'Increasing term insurance is most commonly used to:', '["Fund return of premium and cost of living riders","Cover a declining mortgage balance","Provide level lifetime protection","Replace group coverage after retirement"]'::jsonb, 'Fund return of premium and cost of living riders', 'A rising death benefit is exactly what return of premium and cost of living features require; declining mortgage protection uses decreasing term instead.', 'Increasing term powers ROP and COL riders.', NULL),
('life_types', 'easy', 'Straight (continuous premium) whole life insurance requires premiums to be paid:', '["Until the insured''s death or policy maturity","For exactly ten years","Only until cash value equals the face amount","Until the insured retires"]'::jsonb, 'Until the insured''s death or policy maturity', 'Straight whole life spreads level premiums across the insured''s entire lifetime, ending only at death or the policy''s maturity age.', 'Straight life = pay for life (or to maturity).', NULL),
('life_types', 'medium', 'Compared with straight whole life of the same face amount, a single premium whole life policy:', '["Is fully paid at issue and has immediate substantial cash value","Builds no cash value","Costs less in total premium dollars over a long lifetime","Requires annual evidence of insurability"]'::jsonb, 'Is fully paid at issue and has immediate substantial cash value', 'One lump-sum premium fully funds the contract at issue, creating immediate cash value and no further premium obligation.', 'Single premium WL: paid up on day one, instant cash value.', NULL),
('life_types', 'hard', 'Compared with straight whole life of the same face amount, a 20-pay whole life policy has:', '["Higher annual premiums and faster cash value growth","Lower annual premiums and slower cash value growth","No cash value until the policy is paid up","A decreasing death benefit"]'::jsonb, 'Higher annual premiums and faster cash value growth', 'Compressing lifetime funding into 20 years raises each premium and accelerates cash value accumulation; coverage still lasts for life once paid up.', 'Limited pay: bigger premiums now, faster cash value.', NULL),
('life_types', 'medium', 'When a traditional whole life policy reaches its maturity age, the cash value:', '["Equals the face amount and is paid to the policyowner","Drops to zero","Is forfeited to the insurer","Converts into term insurance"]'::jsonb, 'Equals the face amount and is paid to the policyowner', 'Whole life is designed to endow: at the maturity age the cash value equals the face amount, which is paid out and the contract ends.', 'Whole life endows - cash value meets face at maturity.', NULL),
('life_types', 'medium', 'Adjustable life insurance is distinctive because the policyowner can:', '["Raise or lower the premium, face amount, and protection period as needs change","Invest cash value in mutual fund subaccounts","Skip underwriting for face amount increases","Withdraw dividends tax free"]'::jsonb, 'Raise or lower the premium, face amount, and protection period as needs change', 'Adjustable life lets the owner reconfigure the policy between term-like and whole-life-like designs; face increases still typically require evidence of insurability.', 'Adjustable life: retune premium, face, and period.', NULL)
INSERT INTO public.questions (domain, difficulty, question, options, correct, explanation, know_this, state_specific) VALUES
('life_types', 'medium', 'Under universal life death benefit Option B (Option 2), the beneficiary receives:', '["The face amount plus the accumulated cash value","The face amount only","The cash value only","Twice the face amount"]'::jsonb, 'The face amount plus the accumulated cash value', 'Option A pays a level death benefit (face amount); Option B pays an increasing benefit equal to the face amount plus cash value, at a higher mortality cost.', 'UL Option A = level; Option B = face + cash value.', NULL),
('life_types', 'hard', 'Universal life is described as an "unbundled" product because:', '["The mortality, interest, and expense components are separately disclosed to the policyowner","It has no death benefit","It must be sold with a securities license","Premiums are pooled with other policyholders'' funds"]'::jsonb, 'The mortality, interest, and expense components are separately disclosed to the policyowner', 'UL breaks the contract into visible pieces - cost of insurance charges, credited interest, and expenses - unlike traditional whole life where these are bundled into one premium.', 'UL = transparent mortality, interest, and expense pieces.', NULL),
('life_types', 'medium', 'A universal life policyowner who pays only minimal premiums for several years risks:', '["Policy lapse if the cash value can no longer cover monthly deductions","Automatic conversion to whole life","Forfeiting the death benefit to the insurer permanently","An IRS penalty tax"]'::jsonb, 'Policy lapse if the cash value can no longer cover monthly deductions', 'UL premium flexibility cuts both ways: if funding is too low, cost of insurance and expense deductions can exhaust the cash value and lapse the policy.', 'Underfunded UL can eat itself and lapse.', NULL),
('life_types', 'medium', 'Variable universal life (VUL) combines flexible premiums with:', '["Policyowner-directed investment subaccounts whose performance determines cash value","A guaranteed minimum cash value","Fixed general-account interest only","Automatic annual face increases"]'::jsonb, 'Policyowner-directed investment subaccounts whose performance determines cash value', 'VUL adds separate-account investing to UL''s flexible structure; the policyowner bears investment risk, and selling it requires a securities registration.', 'VUL = flexible premiums + separate-account investing.', NULL),
('life_types', 'hard', 'Indexed universal life (IUL) credits interest based on:', '["The performance of a market index, subject to caps and a guaranteed floor, without direct investment in the index","Direct ownership of index fund shares","The insurer''s dividend scale only","Prevailing bank CD rates"]'::jsonb, 'The performance of a market index, subject to caps and a guaranteed floor, without direct investment in the index', 'IUL cash value earns index-linked interest with downside protection (floor) and limited upside (caps/participation rates); the funds are not actually invested in the market.', 'IUL: index-linked crediting with floor and cap, no direct investment.', NULL),
('life_types', 'medium', 'Variable whole life insurance features:', '["A fixed, level premium with a death benefit that can vary but not fall below a guaranteed minimum","Flexible premiums with no death benefit guarantee","A guaranteed cash value schedule","General account investment only"]'::jsonb, 'A fixed, level premium with a death benefit that can vary but not fall below a guaranteed minimum', 'Variable whole life keeps whole life''s fixed premium but invests cash value in separate accounts; the death benefit fluctuates with performance above a guaranteed floor, while cash value is not guaranteed.', 'Variable WL: fixed premium, floating values, minimum DB floor.', NULL),
('life_types', 'medium', 'A survivorship (second-to-die) life policy is most commonly purchased to:', '["Provide funds for estate settlement costs after both insureds have died","Replace the income of the first spouse to die","Fund a mortgage payoff","Cover a business''s key employee"]'::jsonb, 'Provide funds for estate settlement costs after both insureds have died', 'Second-to-die coverage pays at the second death - exactly when estate taxes and settlement costs typically come due - and is cheaper than two individual policies.', 'Second-to-die pays when estate taxes hit.', NULL),
('life_types', 'easy', 'Under a group life insurance plan, each covered employee receives a:', '["Certificate of insurance as evidence of coverage","Individual policy contract","Copy of the master contract to sign","Surety bond"]'::jsonb, 'Certificate of insurance as evidence of coverage', 'The employer (or other sponsor) holds the master policy; individual participants receive certificates summarizing their coverage.', 'Group life: sponsor holds the policy, employees hold certificates.', NULL),
('life_types', 'medium', 'Group life underwriting differs from individual underwriting because the insurer primarily evaluates:', '["The characteristics of the group as a whole rather than each member''s insurability","Each member''s medical history in detail","Only the oldest member of the group","The plan sponsor''s personal health"]'::jsonb, 'The characteristics of the group as a whole rather than each member''s insurability', 'Group underwriting looks at the group''s size, purpose, turnover, and demographics; individual members typically join without evidence of insurability.', 'Group underwriting judges the group, not the individuals.', NULL),
('life_types', 'medium', 'A noncontributory group life plan (employer pays the entire premium) generally must cover what portion of eligible employees?', '["100 percent","75 percent","50 percent","25 percent"]'::jsonb, '100 percent', 'When employees pay nothing, all eligible employees must be covered to prevent adverse selection; contributory plans typically require around 75 percent participation.', 'Noncontributory = 100% participation; contributory = about 75%.', NULL),
('life_types', 'medium', 'An employee leaving a job typically has how long to convert group life coverage to an individual policy without evidence of insurability?', '["31 days","10 days","6 months","1 year"]'::jsonb, '31 days', 'The standard conversion period is 31 days after termination of group eligibility; during that window the employee remains covered and may convert without proving insurability.', 'Group conversion window = 31 days.', NULL),
('life_types', 'easy', 'Which statement about term life insurance is correct?', '["It provides pure death protection with no cash value accumulation","It always builds cash value slowly","It cannot be renewed or converted","It must be sold with an investment rider"]'::jsonb, 'It provides pure death protection with no cash value accumulation', 'Term insurance is pure protection for a stated period; it accumulates no cash value, which is why its premiums are lower than permanent insurance at issue.', 'Term = pure protection, zero cash value.', NULL),
('life_types', 'medium', 'Industrial (home service) life insurance is characterized by:', '["Small face amounts with premiums collected frequently, often at the insured''s home","Face amounts of $1 million or more","Annual premiums paid by employers","Coverage available only to factory workers"]'::jsonb, 'Small face amounts with premiums collected frequently, often at the insured''s home', 'Industrial or home service life features small policies with weekly or monthly premiums historically collected in person by a debit agent.', 'Industrial life = small policies, frequent home-collected premiums.', NULL),
('life_basics', 'easy', 'In life insurance, insurable interest must exist:', '["At the time the policy is issued","Continuously throughout the policy''s life","Only at the time of the insured''s death","Both at issue and at death"]'::jsonb, 'At the time the policy is issued', 'Life insurance requires insurable interest only at inception; the policy remains valid even if the relationship later ends.', 'Insurable interest: needed at issue, not at death.', NULL),
('life_basics', 'medium', 'Which applicant clearly has an insurable interest in the proposed insured''s life?', '["A business partner who would suffer financial loss at the partner''s death","A stranger who expects to profit from the death","A casual acquaintance from the gym","An investor group with no relationship to the insured"]'::jsonb, 'A business partner who would suffer financial loss at the partner''s death', 'Insurable interest arises from love and affection (close family) or a lawful economic interest in the insured''s continued life - such as a business partner or creditor.', 'Insurable interest = family tie or real economic stake.', NULL),
('life_basics', 'easy', 'Using life insurance to replace a deceased breadwinner''s income for a surviving family illustrates:', '["Survivor protection","Estate conservation","Liquidity for business buyouts","Speculation"]'::jsonb, 'Survivor protection', 'Survivor protection - replacing lost income so dependents can maintain their standard of living - is the most fundamental personal use of life insurance.', 'Survivor protection = income replacement for dependents.', NULL),
('life_basics', 'medium', 'The idea that life insurance instantly provides a large sum at death, regardless of how few premiums were paid, is called:', '["Estate creation","Estate conservation","Adverse selection","Capital retention"]'::jsonb, 'Estate creation', 'Life insurance creates an immediate estate: from the first premium, the full face amount is available at death, something savings alone cannot match.', 'Life insurance creates an immediate estate.', NULL),
('life_basics', 'medium', 'Under the needs approach, which of the following are typical lump-sum (cash) needs at death?', '["Final expenses, mortgage payoff, education funds, and an emergency reserve","Ongoing grocery bills only","The insured''s future raises","Employer payroll taxes"]'::jsonb, 'Final expenses, mortgage payoff, education funds, and an emergency reserve', 'The needs approach totals immediate cash needs (final expenses, debt and mortgage payoff, education, emergency funds) plus ongoing income needs to size coverage.', 'Needs approach: cash needs + income needs.', NULL),
('life_basics', 'hard', 'In survivor income planning, the "blackout period" refers to the years when:', '["A surviving spouse receives no Social Security benefits - after the youngest child leaves home and before the spouse''s retirement benefits begin","All life insurance proceeds are frozen by probate","The insurer may contest the claim","Social Security pays double benefits"]'::jsonb, 'A surviving spouse receives no Social Security benefits - after the youngest child leaves home and before the spouse''s retirement benefits begin', 'Social Security survivor benefits stop when the youngest child reaches the qualifying age and do not resume until the spouse''s own retirement eligibility - life insurance income planning must bridge that gap.', 'Blackout period = the Social Security gap for surviving spouses.', NULL),
('life_basics', 'medium', 'In a cross purchase buy-sell agreement among business partners, life policies are owned by:', '["Each partner on the lives of the other partners","The business entity on each partner","A third-party trustee only","The partners'' spouses"]'::jsonb, 'Each partner on the lives of the other partners', 'In a cross purchase plan each owner buys, pays for, and is beneficiary of policies on the co-owners, using proceeds to buy the deceased''s share; in an entity plan the business owns the policies.', 'Cross purchase: partners insure each other, not the business.', NULL)
INSERT INTO public.questions (domain, difficulty, question, options, correct, explanation, know_this, state_specific) VALUES
('life_basics', 'medium', 'In an entity purchase (stock redemption) buy-sell plan, the life policies funding the agreement are owned and paid for by:', '["The business itself","Each individual owner","The deceased owner''s heirs","An outside investor"]'::jsonb, 'The business itself', 'Under an entity plan, the business owns policies on each owner and uses the proceeds to redeem a deceased owner''s interest - simpler than cross purchase when there are many owners.', 'Entity plan: the business owns the buy-sell policies.', NULL),
('life_basics', 'hard', 'When life insurance informally funds a nonqualified deferred compensation plan for an executive, the policy is typically:', '["Owned by and payable to the employer","Owned by the executive with the employer as beneficiary","Owned jointly by both parties","Assigned to the IRS"]'::jsonb, 'Owned by and payable to the employer', 'Deferred compensation promises are unsecured employer obligations; the employer owns the informally funding policy and uses its values to meet the future obligation to the executive.', 'Deferred comp funding: employer owns and is paid by the policy.', NULL),
('life_basics', 'medium', 'In a key person life insurance arrangement, the applicant, premium payor, and beneficiary are all typically:', '["The business","The key employee","The employee''s family","The company''s lender"]'::jsonb, 'The business', 'The business applies for, owns, pays for, and is beneficiary of key person coverage; the key employee is only the insured and simply consents.', 'Key person: business owns, pays, and collects.', NULL),
('life_basics', 'easy', 'A participating life insurance policy is one that:', '["May pay policy dividends to policyowners","Is sold only by stock insurers","Guarantees a fixed annual dividend","Requires participation in an employer plan"]'::jsonb, 'May pay policy dividends to policyowners', 'Participating policies - traditionally issued by mutual insurers - let policyowners share in divisible surplus through non-guaranteed dividends.', 'Participating = eligible for (never guaranteed) dividends.', NULL),
('life_basics', 'medium', 'Which of the following is NOT one of the three primary factors in life insurance premium determination?', '["Morbidity","Mortality","Interest","Expenses"]'::jsonb, 'Morbidity', 'Life premiums rest on mortality (death rates), interest (investment earnings), and expenses (loading); morbidity - sickness rates - is a health insurance rating factor.', 'Life premiums = mortality + interest + expense. Morbidity is health.', NULL),
('life_basics', 'medium', 'The gross annual premium of a life policy equals the net premium plus:', '["The expense loading","The commissioner''s tax","The dividend accumulation","The reserve requirement"]'::jsonb, 'The expense loading', 'The net premium covers mortality costs discounted for interest; adding the loading for insurer expenses, contingencies, and profit produces the gross premium the customer pays.', 'Gross premium = net premium + expense loading.', NULL),
('life_basics', 'medium', 'Because variable life insurance and variable annuities are securities as well as insurance, they are regulated by:', '["Both state insurance departments and federal securities regulators (SEC/FINRA)","State insurance departments only","The SEC only","The Federal Reserve"]'::jsonb, 'Both state insurance departments and federal securities regulators (SEC/FINRA)', 'Variable products carry investment risk borne by the owner, so they are dually regulated: as insurance by the states and as securities by the SEC and FINRA.', 'Variable products = dual insurance + securities regulation.', NULL),
('life_basics', 'medium', 'A conditional receipt given with the initial premium generally provides that coverage begins:', '["As of the application or exam date, provided the applicant is found insurable as applied for","Immediately and unconditionally","Only when the policy is physically delivered","After the free-look period expires"]'::jsonb, 'As of the application or exam date, provided the applicant is found insurable as applied for', 'The conditional receipt creates coverage retroactive to the application or medical exam date - but only if underwriting later finds the applicant insurable at the rate applied for.', 'Conditional receipt: covered from app date IF found insurable.', NULL),
('life_basics', 'medium', 'If the initial premium was NOT collected with the application, at policy delivery the producer typically must:', '["Collect the premium and obtain a statement of good health from the insured","Simply leave the policy with the applicant","Backdate the policy","Waive the first premium"]'::jsonb, 'Collect the premium and obtain a statement of good health from the insured', 'Without prepayment there was no interim coverage, so the insurer requires the premium plus the insured''s signed statement that their health has not changed since the application.', 'No premium with app = collect premium + good health statement at delivery.', NULL),
('life_basics', 'hard', 'In field underwriting, the producer serves as the:', '["Primary source of information about the applicant and first line of defense against adverse selection","Final authority on risk classification","Medical examiner","Claims adjuster"]'::jsonb, 'Primary source of information about the applicant and first line of defense against adverse selection', 'The producer sees the applicant firsthand, completes the application accurately, and screens obvious misstatements - but the insurer''s underwriter makes the final classification decision.', 'The agent is the front line of underwriting, not the decider.', NULL),
('life_basics', 'medium', 'The Medical Information Bureau (MIB) is best described as:', '["A nonprofit member organization through which insurers share coded medical underwriting information","A government agency that licenses physicians","A credit reporting bureau","A claims payment clearinghouse"]'::jsonb, 'A nonprofit member organization through which insurers share coded medical underwriting information', 'MIB helps member insurers detect misrepresentation by sharing coded prior-application information; an insurer may not decline solely on an MIB code without further investigation.', 'MIB shares codes to catch misrepresentation - never the sole basis to decline.', NULL),
('life_basics', 'medium', 'An underwriter who needs detail about an applicant''s disclosed heart condition would most likely order a(n):', '["Attending physician statement (APS)","Consumer credit report","MIB inquiry alone","Agent''s daily activity report"]'::jsonb, 'Attending physician statement (APS)', 'The APS comes from the physician who treated the applicant and provides detailed clinical history on a specific condition - the best source for medical detail.', 'For medical detail, order the APS.', NULL),
('life_basics', 'medium', 'Before requiring an HIV test in life insurance underwriting, a Wisconsin insurer must:', '["Obtain the applicant''s informed written consent for the test","Notify the applicant''s employer","Obtain a court order","Nothing - consent is not required"]'::jsonb, 'Obtain the applicant''s informed written consent for the test', 'Wisconsin law (s. 631.90) restricts HIV testing in underwriting; testing may occur only with the applicant''s informed consent and with confidentiality protections.', 'HIV testing requires informed consent.', 'Wisconsin'),
('life_basics', 'easy', 'An applicant in excellent health with an ideal build and no risky habits would most likely be classified as:', '["Preferred","Standard","Substandard","Declined"]'::jsonb, 'Preferred', 'Preferred risks present better-than-average mortality expectations and qualify for lower rates than standard risks.', 'Best health = preferred class = lowest rates.', NULL),
('life_basics', 'medium', 'An applicant whose risk is so severe that the insurer will not issue coverage at any premium is classified as:', '["Declined","Substandard","Standard","Preferred"]'::jsonb, 'Declined', 'Substandard risks can still be insured with rated (higher) premiums; a declined risk is uninsurable by that insurer at any price.', 'Substandard = rated up; declined = no policy at any price.', NULL),
('annuities', 'easy', 'The person whose life expectancy determines the amount and duration of annuity income payments is the:', '["Annuitant","Owner","Beneficiary","Producer"]'::jsonb, 'Annuitant', 'The annuitant is the measuring life for income payments; the owner controls the contract, and the beneficiary receives any death benefit. The annuitant must be a natural person.', 'Annuitant = the measuring life.', NULL),
('annuities', 'easy', 'The primary risk an annuity''s lifetime income feature protects against is:', '["Outliving one''s income (longevity risk)","Dying too soon","Inflation","Market volatility"]'::jsonb, 'Outliving one''s income (longevity risk)', 'Life insurance protects against dying too soon; annuities protect against living too long by guaranteeing income that cannot be outlived.', 'Annuities insure against living too long.', NULL),
('annuities', 'medium', 'A deferred annuity may be funded with:', '["Either a single premium or flexible periodic premiums","A single premium only","Employer contributions only","Policy dividends only"]'::jsonb, 'Either a single premium or flexible periodic premiums', 'Deferred annuities accept a lump sum (single premium deferred annuity) or ongoing flexible payments during the accumulation period; immediate annuities require a single premium.', 'Deferred = single or flexible premiums; immediate = single only.', NULL),
('annuities', 'medium', 'Surrender charges in a deferred annuity typically:', '["Decline each year and eventually disappear","Increase over time","Remain level for the life of the contract","Apply only after annuitization"]'::jsonb, 'Decline each year and eventually disappear', 'Surrender charge schedules start at a set percentage and grade down annually to zero after the surrender period, discouraging early withdrawal.', 'Surrender charges melt away over the schedule.', NULL),
('annuities', 'medium', 'If a deferred annuity owner dies during the accumulation period, the contract typically pays the beneficiary:', '["At least the greater of premiums paid or the contract value","Nothing - the insurer keeps the funds","Only the surrender charges","The face amount of a companion life policy"]'::jsonb, 'At least the greater of premiums paid or the contract value', 'Deferred annuities carry an accumulation-period death benefit so the insurer does not keep the funds; the beneficiary generally receives the greater of premiums or accumulated value.', 'Death in accumulation: beneficiary gets premiums or value, whichever is more.', NULL)
INSERT INTO public.questions (domain, difficulty, question, options, correct, explanation, know_this, state_specific) VALUES
('annuities', 'easy', 'Whereas life insurance creates an estate at death, an annuity is best described as a vehicle that:', '["Systematically liquidates a sum of money over time","Builds an estate for heirs","Insures against accidental death","Guarantees stock market returns"]'::jsonb, 'Systematically liquidates a sum of money over time', 'Life insurance creates an estate; an annuity scientifically liquidates one, converting principal into an income stream the owner cannot outlive.', 'Life insurance creates; annuities liquidate.', NULL),
('annuities', 'medium', 'Which annuity payout option provides the largest periodic payment for a given premium?', '["Life only (pure life)","Life with 20-year period certain","Joint and survivor","Installment refund"]'::jsonb, 'Life only (pure life)', 'Life only pays for the annuitant''s lifetime with nothing to survivors, so with no guarantees to fund, each payment is largest. Every added guarantee reduces the payment.', 'More guarantees = smaller checks. Life only pays the most.', NULL),
('annuities', 'medium', 'Under a life annuity with 10-year period certain, if the annuitant dies in year 4, the insurer:', '["Continues payments to the beneficiary for the remaining 6 years of the certain period","Stops all payments immediately","Refunds all premiums in a lump sum","Pays the beneficiary for the beneficiary''s lifetime"]'::jsonb, 'Continues payments to the beneficiary for the remaining 6 years of the certain period', 'Life with period certain pays for the longer of the annuitant''s life or the guaranteed period; death within the period sends the remaining certain payments to the beneficiary.', 'Period certain = guaranteed minimum years of payments.', NULL),
('annuities', 'medium', 'A cash refund life annuity guarantees that:', '["If the annuitant dies before receiving payments equal to the premium, the beneficiary receives the difference in a lump sum","Payments continue forever to heirs","The annuitant may cancel and reinvest at any time","Payments increase with inflation"]'::jsonb, 'If the annuitant dies before receiving payments equal to the premium, the beneficiary receives the difference in a lump sum', 'Refund options ensure at least the purchase payment comes back: cash refund pays the shortfall as a lump sum, installment refund continues the periodic payments until the premium is recovered.', 'Refund annuity: at least your money back, lump sum or installments.', NULL),
('annuities', 'medium', 'An "annuity certain" differs from a life annuity because it:', '["Pays for a fixed period or fixed amount with no life contingency","Requires medical underwriting","Pays only while the annuitant lives","Never involves an insurance company"]'::jsonb, 'Pays for a fixed period or fixed amount with no life contingency', 'Annuities certain pay a set period or amount regardless of survival - there is no mortality element, so payments simply go to the beneficiary if the owner dies.', 'Annuity certain = fixed payout, no life contingency.', NULL),
('annuities', 'medium', 'Premiums paid into a fixed annuity are held in the insurer''s:', '["General account, with the insurer bearing the investment risk","Separate account, with the owner bearing the investment risk","Escrow account at a bank","Policyowner-directed brokerage account"]'::jsonb, 'General account, with the insurer bearing the investment risk', 'Fixed annuities are backed by the insurer''s general account and guarantee minimum interest - the insurer, not the owner, bears investment risk. Variable annuity funds go to the separate account.', 'Fixed = general account, insurer''s risk. Variable = separate account, owner''s risk.', NULL),
('annuities', 'medium', 'During the accumulation phase of a variable annuity, the owner''s premium purchases:', '["Accumulation units in the separate account","Annuity units at a fixed price","Shares of the insurer''s stock","Guaranteed interest certificates"]'::jsonb, 'Accumulation units in the separate account', 'Variable annuity contributions buy accumulation units whose value fluctuates with subaccount performance; at annuitization they convert to annuity units.', 'Accumulate in accumulation units; get paid in annuity units.', NULL),
('annuities', 'hard', 'After a variable annuity is annuitized, the number of annuity units credited to the payee:', '["Remains fixed, while the value of each unit fluctuates with investment performance","Fluctuates monthly with the market","Increases with each payment","Is reset annually by the insurer"]'::jsonb, 'Remains fixed, while the value of each unit fluctuates with investment performance', 'Annuitization locks in a fixed number of annuity units per payment; the dollar amount varies because each unit''s value tracks separate account performance.', 'Fixed number of units, floating unit value.', NULL),
('annuities', 'medium', 'The guaranteed minimum interest floor of an indexed annuity means the owner:', '["Is protected from index losses while sharing in part of index gains","Receives the full index return including losses","Owns index fund shares directly","Gets unlimited upside with no downside"]'::jsonb, 'Is protected from index losses while sharing in part of index gains', 'Indexed annuities credit index-linked interest subject to caps and participation rates, but a guaranteed floor prevents loss of credited principal when the index falls.', 'Indexed annuity: share the upside, floor under the downside.', NULL),
('annuities', 'hard', 'An indexed annuity with an 80% participation rate credits interest equal to:', '["80% of the measured index gain, subject to any cap","The full index gain minus 80%","80% of the premium paid","A flat 80% return"]'::jsonb, '80% of the measured index gain, subject to any cap', 'The participation rate is the share of the index increase used to calculate credited interest; caps then limit the maximum credit in a period.', 'Participation rate = your slice of the index gain.', NULL),
('annuities', 'hard', 'A market value adjusted (MVA) annuity differs from an ordinary fixed annuity because:', '["Early surrenders are adjusted up or down based on changes in market interest rates since purchase","Its income payments track a stock index","It has no surrender charges","The insurer may cancel the contract at will"]'::jsonb, 'Early surrenders are adjusted up or down based on changes in market interest rates since purchase', 'The MVA shifts interest rate risk to the owner at surrender: if rates rose since issue the surrender value is adjusted down, and if rates fell it is adjusted up.', 'MVA: surrender value moves opposite to interest rates.', NULL),
('annuities', 'medium', 'A guaranteed lifetime withdrawal benefit (GLWB) rider allows the annuity owner to:', '["Withdraw a guaranteed income for life without annuitizing the contract","Avoid all surrender charges","Convert the annuity into life insurance","Guarantee the account value never declines"]'::jsonb, 'Withdraw a guaranteed income for life without annuitizing the contract', 'Guaranteed living benefit riders promise lifetime income while the owner keeps control of the remaining account value, unlike traditional annuitization which is irrevocable.', 'GLWB = lifetime income without giving up the contract.', NULL),
('annuities', 'medium', 'Annuities are frequently used to distribute large lump-sum settlements (such as lawsuit awards) because they:', '["Convert the lump sum into a managed stream of income the recipient cannot easily outlive or exhaust","Eliminate all taxes on the award","Double the settlement amount","Are required by federal court rules"]'::jsonb, 'Convert the lump sum into a managed stream of income the recipient cannot easily outlive or exhaust', 'Structured settlements use annuities to turn a lump sum into scheduled income, protecting recipients from prematurely exhausting the funds.', 'Structured settlements = annuitized lawsuit money.', NULL),
('annuities', 'medium', 'The difference between a qualified and a nonqualified annuity is that a qualified annuity:', '["Is funded with pre-tax dollars inside a tax-favored retirement plan","Guarantees higher interest rates","Has no contribution limits","Is exempt from required minimum distributions"]'::jsonb, 'Is funded with pre-tax dollars inside a tax-favored retirement plan', 'Qualified annuities sit inside IRAs or employer plans and follow those plans'' contribution limits and distribution rules; nonqualified annuities are bought with after-tax dollars and have no IRS contribution limit.', 'Qualified = pre-tax plan money; nonqualified = after-tax money.', NULL),
('annuities', 'hard', 'When a producer recommends exchanging an older annuity for a new one, a key suitability concern is that the exchange may:', '["Trigger new surrender charges and restart the surrender period","Always increase the death benefit","Eliminate the owner''s tax deferral permanently","Be prohibited by federal law"]'::jsonb, 'Trigger new surrender charges and restart the surrender period', 'Exchanges can impose surrender charges on the old contract and lock the client into a fresh surrender schedule on the new one - a classic churning red flag that suitability review must weigh.', 'Annuity swaps restart the surrender clock - scrutinize them.', NULL),
('annuities', 'medium', 'Once a deferred annuity owner elects to annuitize under a life income option, the decision is:', '["Generally irrevocable - the accumulated value is converted permanently into income payments","Reversible within five years","Reversible with a 10% fee","Automatically reversed at age 90"]'::jsonb, 'Generally irrevocable - the accumulated value is converted permanently into income payments', 'Annuitization permanently exchanges the account balance for an income stream; the owner can no longer take lump-sum withdrawals from the converted value.', 'Annuitization is a one-way door.', NULL),
('general_insurance', 'medium', 'Which characteristic would make a risk uninsurable?', '["The chance of both loss and gain (a speculative risk)","A loss that is definite and measurable","A loss that is accidental from the insured''s standpoint","A large number of similar exposure units"]'::jsonb, 'The chance of both loss and gain (a speculative risk)', 'Only pure risks - loss or no loss, with no chance of gain - are insurable; speculative risks like gambling or market investing are not.', 'Insurance covers pure risk only, never speculative risk.', NULL),
('general_insurance', 'easy', 'Purchasing insurance is the most common example of which method of handling risk?', '["Transfer","Avoidance","Retention","Reduction"]'::jsonb, 'Transfer', 'Insurance shifts the financial consequences of loss from the insured to the insurer in exchange for premium - the classic risk transfer.', 'Buying insurance = transferring risk.', NULL),
('general_insurance', 'easy', 'A person who refuses to ever fly on airplanes to eliminate any chance of dying in a plane crash is handling risk through:', '["Avoidance","Transfer","Sharing","Retention"]'::jsonb, 'Avoidance', 'Avoidance eliminates exposure to a risk entirely by not engaging in the activity; retention accepts the risk, and reduction merely lessens it.', 'Avoidance = never expose yourself to the risk at all.', NULL),
('general_insurance', 'medium', 'The authority specifically granted to a producer in the written agency agreement with the insurer is:', '["Express authority","Implied authority","Apparent authority","Assumed authority"]'::jsonb, 'Express authority', 'Express authority is what the contract explicitly grants; implied authority covers acts reasonably necessary to carry it out, and apparent authority arises from what the public reasonably believes.', 'Express = written in the agency contract.', NULL),
('general_insurance', 'medium', 'Representations made on a life insurance application are typically:','["Statements the applicant asserts to be true to the best of their knowledge","Warranties that must be literally and completely accurate","Guarantees of future performance","Conditions that must be met before any claim is paid"]'::jsonb, 'Statements the applicant asserts to be true to the best of their knowledge', 'Representations are assertions believed true; warranties must be literally true. Misstatement of a representation does not void the policy after the contestable period ends.', 'Representation = believed true. Warranty = must be literally true.', NULL),
('general_insurance', 'hard', 'Concealment in insurance means:', '["The applicant intentionally withholds material facts that the insurer would consider in making a decision","The applicant misstates facts disclosed","The insurer hides information from the applicant","A policy provision is not clearly readable"]'::jsonb, 'The applicant intentionally withholds material facts that the insurer would consider in making a decision', 'Concealment is deliberate suppression of a material fact; fraud adds a misstatement. An innocent failure to mention something is neither.', 'Concealment = deliberately hiding material facts.', NULL),
('general_insurance', 'medium', 'Waiver in insurance means that the insurer has:', '["Relinquished a known right, typically in writing or by conduct","Agreed to pay a claim that is not covered","Reduced the premium without the underwriter''s approval","Changed the beneficiary designation"]'::jsonb, 'Relinquished a known right, typically in writing or by conduct', 'Waiver is a voluntary surrender of a right; it requires the insurer to know of the right and intentionally give it up.', 'Waiver = giving up a known right.', NULL),
('general_insurance', 'medium', 'Estoppel in insurance means that an insurer is prevented from:','["Denying a claim after acting in a way that led the insured to believe a right had been waived","Issuing a policy at a higher rate than applied for","Canceling a policy for nonpayment during the grace period","Requiring the insured to attend their own autopsy"]'::jsonb, 'Denying a claim after acting in a way that led the insured to believe a right had been waived', 'Estoppel bars an insurer from asserting a right when its conduct has led the other party to reasonably rely on waiving it.', 'Estoppel = you can''t claim a right after you acted like you didn''t have it.', NULL),
('general_insurance', 'medium', 'Among insurers, a stock company is best characterized as one that is:','["Owned by shareholders who may or may not be policyholders","Owned exclusively by policyholders who share dividends","Organized as a fraternal benefit society","Operated by the government"]'::jsonb, 'Owned by shareholders who may or may not be policyholders', 'Stock insurers issue common and preferred shares to outside investors; dividends go to shareholders based on investment performance. Mutual insurers are owned by policyholders.', 'Stock insurer = shareholder-owned; mutual = policyholder-owned.', NULL)
INSERT INTO public.questions (domain, difficulty, question, options, correct, explanation, know_this, state_specific) VALUES
('taxation', 'easy', 'Life insurance death benefits paid to a named beneficiary are generally:','["Income-tax free to the beneficiary","Taxable as ordinary income to the beneficiary","Taxable to the insured''s estate only","Subject to a 10% penalty if received before age 59.5"]'::jsonb, 'Income-tax free to the beneficiary', 'Section 101(a) of the Internal Revenue Code exempts life insurance death benefits from federal income tax when paid to a named beneficiary.', 'Death benefits are income-tax free (I.R.C. s. 101).', NULL),
('taxation', 'medium', 'Which of the following is tax-deferred in a life insurance contract?','["The growth of cash value (but not policy loans or surrenders)","Premium payments","Dividend elections","The face amount at death"]'::jsonb, 'The growth of cash value (but not policy loans or surrenders)', 'Cash value growth inside the policy is not currently taxable; tax is deferred until withdrawal, loan, or surrender.', 'Policy cash value grows tax-deferred.', NULL),
('taxation', 'medium', 'A Modified Endowment Contract (MEC) is a life insurance policy that:','["Fails the 7-pay test and loses certain favorable tax benefits on distributions","Is endorsed for use only in the military","Is required to have a minimum face amount of $250,000","Cannot be assigned to a third party"]'::jsonb, 'Fails the 7-pay test and loses certain favorable tax benefits on distributions', 'An MEC is created when premiums paid in the first seven years exceed what the 7-pay test allows; distributions from an MEC are taxed like annuity distributions.', 'MEC = fails 7-pay test, loses favorable distribution tax treatment.', NULL),
('taxation', 'hard', 'Under the 7-pay test, if total premiums paid in the first seven years exceed the limit:','["The policy becomes an MEC and distributions are taxed income-first, with a 10% penalty if taken before age 59.5","The policy is void and the insured must reapply","Premiums refunded for overpayment","The death benefit is reduced proportionally"]'::jsonb, 'The policy becomes an MEC and distributions are taxed income-first, with a 10% penalty if taken before age 59.5', 'Exceeding the 7-pay test creates an MEC; thereafter distributions are taxed on an income-first basis with a penalty (except at death, disability, or as qualified periodic payments).', '7-pay limit exceeded = MEC created, unfavorable tax treatment.', NULL),
('taxation', 'medium', 'A Section 1035 exchange permits a policyholder to:','["Exchange one life insurance or annuity policy for another, without triggering current taxation of gain","Deduct policy premiums from taxable income","Receive a tax credit for life insurance purchased","Exclude all investment gains from taxation"]'::jsonb, 'Exchange one life insurance or annuity policy for another, without triggering current taxation of gain', 'A 1035 exchange is a tax-free swap of insurance or annuity contracts; the basis carries over, and tax recognition is deferred until distribution from the new contract.', '1035 exchange = tax-free policy-to-policy swap.', NULL),
('taxation', 'medium', 'If a life insurance policy is surrendered for cash value greater than the premiums paid:','["The gain is taxable as ordinary income, but only the gain amount, not the full surrender value","The entire surrender value is taxable","No tax is due, as insurance is always tax-free","The insured receives a tax credit"]'::jsonb, 'The gain is taxable as ordinary income, but only the gain amount, not the full surrender value', 'On surrender, taxable gain = cash value minus cost basis (premiums paid minus any prior taxable distributions). Only the gain is taxable, not the return of premium.', 'Surrender gain = cash value minus premiums paid.', NULL),
('taxation', 'hard', 'The "transfer for value" rule means that if a life insurance policy is transferred for something of value (money, another policy, etc.) to a party without an insurable interest:','["The death benefit may become taxable income to the recipient to the extent it exceeds the consideration paid","Death benefits are always tax-free regardless of transfer","The policy is voided","The insured must be notified within 30 days"]'::jsonb, 'The death benefit may become taxable income to the recipient to the extent it exceeds the consideration paid', 'A transfer-for-value to a non-insurable-interest party can make the death benefit taxable income. Exceptions include transfer to a business partner or within corporate reorganizations.', 'Transfer for value = some of death benefit may be taxable.', NULL)
INSERT INTO public.questions (domain, difficulty, question, options, correct, explanation, know_this, state_specific) VALUES
('qualified_plans', 'easy', 'A key requirement for a retirement plan to receive favorable federal tax-qualified status is that it must:','["Be established with a written plan document and operated for the exclusive benefit of employees","Generate the maximum possible employer profit","Have unlimited contribution limits","Be administered by only one individual"]'::jsonb, 'Be established with a written plan document and operated for the exclusive benefit of employees', 'Tax qualification requires a written plan, proper employee classification, fiduciary administration, and benefit distribution tied to retirement, not employer profit.', 'Qualified plan = written document, employee benefit exclusive.', NULL),
('qualified_plans', 'medium', 'Contributions to a traditional IRA are generally deductible by the worker:','["If the worker has earned income and is not covered by an employer retirement plan, or if income falls below phase-out limits","Only if the worker is self-employed","Only for workers over age 50","Contributions are never deductible"]'::jsonb, 'If the worker has earned income and is not covered by an employer retirement plan, or if income falls below phase-out limits', 'Traditional IRA contributions are deductible if the worker has earned income and either lacks employer-plan coverage or their income is below the phase-out limit.', 'Traditional IRA deductibility subject to earned income and income limits.', NULL),
('qualified_plans', 'medium', 'A Simplified Employee Pension (SEP) plan is attractive to small employers and self-employed persons because:','["Contributions are flexible and made directly to employee IRAs, with minimal administrative burden","It requires annual actuarial valuations","It mandates 401(k)-style employee deferrals","Employees may not withdraw funds until age 59.5"]'::jsonb, 'Contributions are flexible and made directly to employee IRAs, with minimal administrative burden', 'SEPs let employers contribute to traditional IRAs for each eligible employee with minimal paperwork; contribution amounts can vary year to year.', 'SEP = flexible employer contributions to employee IRAs.', NULL),
('qualified_plans', 'hard', 'Required minimum distributions (RMDs) from a traditional IRA must generally begin by:','["Age 73 (under the SECURE Act 2.0)","Age 59.5 (to avoid the 10% penalty)","Age 65 (for qualified employees)","Never, if the account has been accumulating less than 10 years"]'::jsonb, 'Age 73 (under the SECURE Act 2.0)', 'The SECURE Act 2.0 raised the RMD start age from 72 to 73, effective in 2023. Failure to take RMDs incurs a 25% penalty on the shortfall (reduced to 10% under certain conditions).', 'RMD age now 73 under SECURE Act 2.0.', NULL),
('qualified_plans', 'medium', 'A 403(b) tax-sheltered annuity plan is typically available to:','["Employees of public schools, colleges, universities, hospitals, and certain other nonprofit organizations","All employees of for-profit businesses","Self-employed individuals with no employees","Only government workers"]'::jsonb, 'Employees of public schools, colleges, universities, hospitals, and certain other nonprofit organizations', 'Section 403(b) plans are limited to certain nonprofits and public-sector employees; they function like 401(k)s but are annuity-based and carry lower administrative requirements.', '403(b) = nonprofit and public-sector employees'' tax-deferred annuities.', NULL)
